{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "The selected research studies had to meet the following inclusion criteria: (1) being original, (2) based on qualitative and/or quantitative methods, (3) with any methodological design, (4) submitted for peer-review, (5) published in English, Spanish, French, Italian or Portuguese, (6) completed after December 2019, (7) without geographic limitation, (8) with at least the abstract available, and (9) that in their results evaluated the impact of possible exposure to SARS-CoV-2 on levels of stress, anxiety, depression and/or self-efficacy of the HPs who were working in public, private, or voluntary out-of-hospital EMS during the COVID-19 pandemic or identified factors related positively or negatively with these levels or compared them with those obtained in other working environments and/or professional categories.",
      "reason": "The methods section lists explicit study characteristics used to determine eligibility: study designs, qualitative/quantitative methods, submission/peer-review status, languages, date cutoff, geographic scope, abstract availability, settings (out-of-hospital EMS), and outcomes of interest."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "The selected research studies had to meet the following inclusion criteria: ... (4) submitted for peer-review, (5) published in English, Spanish, French, Italian or Portuguese, (6) completed after December 2019, ...",
      "reason": "The eligibility criteria explicitly specify report characteristics including publication/language requirements and a date restriction (completed after December 2019) and peer-review/publication status."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "PARTIAL",
      "chunk_id": "text_3",
      "quote": "Opinion articles and editorials, studies of low scientific-technical quality, those that did not reply to the posed research question and/or were not in line with the objective of the review, as well as others that, despite including out-of-hospital HPs, contributed no specific data on this subgroup in their results were excluded.",
      "reason": "The review explicitly states exclusion of studies that \"contributed no specific data on this subgroup\" (i.e., outcome results for the subgroup not reported). However, there is no explicit statement distinguishing exclusion of studies because outcomes were not measured versus simply not reported, so the distinction is only partly addressed."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The retrieved methods/results describe individual study groupings (e.g., Health vs Emergency groups in included studies) and present a narrative synthesis, but do not specify review-level groups used in each synthesis nor explicitly link such groups to the comparisons defined in the review objectives."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PARTIAL",
      "chunk_id": "text_3",
      "quote": "High methodological quality was established for the inclusion of studies in the review.",
      "reason": "The review provides a rationale for restricting inclusion to studies of high methodological quality via JBI appraisal (explicitly stating high methodological quality was required). However, rationales for other notable restrictions (e.g., language limits, date cutoff) are not explained in the retrieved evidence, so rationale information is incomplete."
    }
  ],
  "confidence": 80
}

